import { Hono } from 'hono';
import { getUserId, getAppType } from '../middleware/auth.js';
import { db } from '../db/index.js';
import { users } from '../db/schema.js';
import { eq } from 'drizzle-orm';
import { createClerkClient } from '@clerk/backend';
import { getClerkClient } from '../utils/clerk-client.js';
import { posthog } from '../services/posthog.js';

const authRoutes = new Hono();

// An authenticated ping endpoint that returns the Clerk user ID.
authRoutes.get('/ping', (c) => {
  const userId = getUserId(c);
  return c.json({ ok: true, userId });
});

// Submit onboarding questionnaire
authRoutes.post('/onboarding', async (c) => {
  const clerkUserId = getUserId(c);
  const appType = getAppType(c);

  try {
    const body = await c.req.json();
    const { persona, discoveryChannel, wantsInterview } = body as {
      persona: string;
      discoveryChannel: string;
      wantsInterview: boolean;
    };

    // Validate required fields
    if (!persona || !discoveryChannel || wantsInterview === undefined) {
      return c.json({ ok: false, error: 'Missing required fields' }, 400);
    }

    // Get user email from Clerk for the interview tracking
    const clerkClient = getClerkClient(appType);
    let userEmail: string | null = null;

    if (clerkClient) {
      try {
        const clerkUser = await clerkClient.users.getUser(clerkUserId);
        userEmail = clerkUser?.emailAddresses?.[0]?.emailAddress ?? null;

        // Update Clerk user metadata to mark onboarding as complete
        await clerkClient.users.updateUserMetadata(clerkUserId, {
          publicMetadata: {
            ...clerkUser.publicMetadata,
            onboardingCompleted: true,
            onboardingCompletedAt: new Date().toISOString(),
          },
        });
      } catch (err) {
        console.error('Failed to update Clerk metadata:', err);
        // Continue even if metadata update fails
      }
    }

    // Capture the event in PostHog
    posthog.captureEvent(
      {
        userId: clerkUserId,
        persona,
        discoveryChannel,
        wantsInterview,
        userEmail, // Always include email for analytics
        timestamp: new Date().toISOString(),
      },
      'onboarding_questionnaire_completed'
    );

    // If user wants interview, capture a separate event for easy tracking
    if (wantsInterview) {
      posthog.captureEvent(
        {
          userId: clerkUserId,
          userEmail,
          persona,
          discoveryChannel,
          timestamp: new Date().toISOString(),
        },
        'user_interview_interest'
      );
    }

    return c.json({ ok: true });
  } catch (err) {
    console.error('Failed to process onboarding:', err);
    return c.json({ ok: false, error: 'Failed to process onboarding' }, 500);
  }
});

// Delete the authenticated user's account
authRoutes.delete('/delete', async (c) => {
  const clerkUserId = getUserId(c);

  // Delete from application DB
  try {
    await db.delete(users).where(eq(users.clerkId, clerkUserId));
  } catch (err) {
    console.error('Failed to delete user from DB', err);
    return c.json({ ok: false, error: 'Failed to delete user from DB' }, 500);
  }

  // Delete from Clerk (skip in dev if CLERK_SECRET_KEY missing)
  if (process.env.CLERK_SECRET_KEY) {
    try {
      const clerk = createClerkClient({
        secretKey: process.env.CLERK_SECRET_KEY,
      });
      await clerk.users.deleteUser(clerkUserId);
    } catch (err) {
      console.error('Failed to delete user from Clerk', err);
      // Even if Clerk deletion fails, we already removed from DB. Return error.
      return c.json(
        { ok: false, error: 'Failed to delete user from Clerk' },
        500
      );
    }
  }

  return c.json({ ok: true });
});

export default authRoutes;

import { OpenAPIHono } from '@hono/zod-openapi';
import { db } from '../db/index.js';
import { userCredentials } from '../db/schema.js';
import {
  type CredentialResponse,
  type CreateCredentialResponse,
  type UpdateCredentialResponse,
  CredentialType,
  DatabaseMetadata,
} from '../schemas/index.js';
import { getUserId } from '../middleware/auth.js';
import { CredentialEncryption } from '../utils/encryption.js';
import { eq, and } from 'drizzle-orm';
import {
  listCredentialsRoute,
  createCredentialRoute,
  updateCredentialRoute,
  deleteCredentialRoute,
  getCredentialMetadataRoute,
} from '../schemas/credentials.js';
import {
  setupErrorHandler,
  validationErrorHook,
} from '../utils/error-handler.js';
import { CredentialValidator } from '../services/credential-validator.js';

const app = new OpenAPIHono({
  defaultHook: validationErrorHook,
});
setupErrorHandler(app);

app.openapi(listCredentialsRoute, async (c) => {
  const userId = getUserId(c);

  const credentials = await db.query.userCredentials.findMany({
    where: eq(userCredentials.userId, userId),
    columns: {
      id: true,
      credentialType: true,
      name: true,
      metadata: true,
      createdAt: true,
      isOauth: true,
      oauthExpiresAt: true,
      oauthScopes: true,
      oauthProvider: true,
    },
  });

  const response: CredentialResponse[] = credentials.map((cred) => {
    const now = new Date();
    let oauthStatus: 'active' | 'expired' | 'needs_refresh' | undefined;

    // Calculate OAuth status if this is an OAuth credential
    if (cred.isOauth && cred.oauthExpiresAt) {
      const expiresAt = new Date(cred.oauthExpiresAt);
      const fiveMinutesFromNow = new Date(now.getTime() + 5 * 60 * 1000);

      if (expiresAt < now) {
        oauthStatus = 'expired';
      } else if (expiresAt < fiveMinutesFromNow) {
        oauthStatus = 'needs_refresh';
      } else {
        oauthStatus = 'active';
      }
    }

    return {
      id: cred.id,
      credentialType: cred.credentialType,
      name: cred.name || undefined,
      metadata: cred.metadata || { tables: {}, rules: [] },
      createdAt: cred.createdAt.toISOString(),

      // OAuth fields
      isOauth: cred.isOauth || undefined,
      oauthProvider: cred.oauthProvider || undefined,
      oauthExpiresAt: cred.oauthExpiresAt?.toISOString() || undefined,
      oauthScopes: cred.oauthScopes || undefined,
      oauthStatus,
    };
  });

  return c.json(response, 200);
});

app.openapi(createCredentialRoute, async (c) => {
  const userId = getUserId(c);
  const {
    credentialType,
    value,
    name,
    skipValidation,
    credentialConfigurations,
    metadata,
  } = c.req.valid('json');

  // Validate credential before storing
  const validationResult = await CredentialValidator.validateCredential(
    credentialType,
    value,
    skipValidation || false,
    credentialConfigurations
  );

  if (!validationResult.isValid) {
    return c.json(
      {
        error: 'Credential validation failed',
        details: validationResult.error,
        bubbleName: validationResult.bubbleName,
      },
      400
    );
  }

  // Encrypt the credential value
  const encryptedValue = await CredentialEncryption.encrypt(value);

  // Store in database
  const [inserted] = await db
    .insert(userCredentials)
    .values({
      userId,
      credentialType,
      encryptedValue,
      name,
      metadata,
    })
    .returning({ id: userCredentials.id });

  const response: CreateCredentialResponse = {
    id: inserted.id,
    message: 'Credential created successfully',
  };

  return c.json(response, 201);
});

app.openapi(updateCredentialRoute, async (c) => {
  const userId = getUserId(c);
  const credentialId = parseInt(c.req.param('id'));
  const { value, name, skipValidation, credentialConfigurations, metadata } =
    c.req.valid('json');

  if (isNaN(credentialId)) {
    return c.json({ error: 'Invalid credential ID format' }, 400);
  }

  // Check if credential exists and belongs to user
  const credential = await db.query.userCredentials.findFirst({
    where: and(
      eq(userCredentials.id, credentialId),
      eq(userCredentials.userId, userId)
    ),
  });

  if (!credential) {
    return c.json({ error: 'Credential not found or access denied' }, 404);
  }

  // Prepare update data
  const updateData: {
    name?: string;
    encryptedValue?: string;
    metadata?: DatabaseMetadata;
  } = {};

  // Only update name if provided
  if (name !== undefined) {
    updateData.name = name;
  }

  // Only update metadata if provided
  if (metadata !== undefined) {
    updateData.metadata = metadata;
  }

  // Handle value update with proper validation
  if (value !== undefined) {
    // If value is provided, it must not be empty
    if (!value || value.trim() === '') {
      return c.json(
        {
          error: 'Credential value cannot be empty',
          details: 'A valid credential value is required',
        },
        400
      );
    }

    // Validate credential before updating
    const validationResult = await CredentialValidator.validateCredential(
      credential.credentialType as CredentialType,
      value,
      skipValidation || false,
      credentialConfigurations
    );

    if (!validationResult.isValid) {
      return c.json(
        {
          error: 'Credential validation failed',
          details: validationResult.error,
          bubbleName: validationResult.bubbleName,
        },
        400
      );
    }

    // Encrypt the new credential value
    const encryptedValue = await CredentialEncryption.encrypt(value);
    updateData.encryptedValue = encryptedValue;
  }

  // Update the credential
  const [updated] = await db
    .update(userCredentials)
    .set(updateData)
    .where(eq(userCredentials.id, credentialId))
    .returning({ id: userCredentials.id });

  const response: UpdateCredentialResponse = {
    id: updated.id,
    message: 'Credential updated successfully',
  };

  return c.json(response, 200);
});

app.openapi(deleteCredentialRoute, async (c) => {
  const userId = getUserId(c);
  const credentialId = parseInt(c.req.param('id'));

  if (isNaN(credentialId)) {
    return c.json({ error: 'Invalid credential ID format' }, 400);
  }

  // Check if credential exists and belongs to user
  const credential = await db.query.userCredentials.findFirst({
    where: and(
      eq(userCredentials.id, credentialId),
      eq(userCredentials.userId, userId)
    ),
  });

  if (!credential) {
    return c.json({ error: 'Credential not found or access denied' }, 404);
  }

  // Delete the credential
  await db.delete(userCredentials).where(eq(userCredentials.id, credentialId));

  return c.json({ message: 'Credential deleted successfully' }, 200);
});

app.openapi(getCredentialMetadataRoute, async (c) => {
  const userId = getUserId(c);
  const credentialId = parseInt(c.req.param('id'));

  if (isNaN(credentialId)) {
    return c.json({ error: 'Invalid credential ID format' }, 400);
  }

  // Check if credential exists and belongs to user
  const credential = await db.query.userCredentials.findFirst({
    where: and(
      eq(userCredentials.id, credentialId),
      eq(userCredentials.userId, userId)
    ),
  });

  if (!credential) {
    return c.json({ error: 'Credential not found or access denied' }, 404);
  }

  // Either the access token (OAuth) or the encrypted value (API key)
  const credentialValue =
    credential.encryptedValue || credential.oauthAccessToken;

  if (!credentialValue) {
    console.error(`Credential ${credential.id} has no valid credential value - isOauth: 
  ${credential.isOauth}`);
    return c.json({ error: 'Credential data is invalid' }, 400);
  }

  // Get metadata from the credential using the validator
  const metadata = await CredentialValidator.getEncryptedCredentialMetadata(
    credential.credentialType as CredentialType,
    credentialValue
  );

  return c.json(metadata || null, 200);
});

export default app;

import { db } from '../db/index.js';
import { userCredentials } from '../db/schema.js';
import { eq, and, inArray } from 'drizzle-orm';
import { CredentialEncryption } from '../utils/encryption.js';
// CredentialType imported for future use in credential validation
import type { ParsedBubble } from '@bubblelab/shared-schemas';
import type { CredentialMetadata } from '@bubblelab/shared-schemas';
import { oauthService } from './oauth-service.js';

export interface UserCredentialMapping {
  varName: string;
  secret: string;
  credentialType: string; // The credential type from the database (e.g., 'OPENAI_CRED', 'SLACK_CRED')
  credentialId: number;
  metadata?: CredentialMetadata; // Credential metadata (DatabaseMetadata or JiraOAuthMetadata)
  /** User-assigned credential name (used for credential pool metadata) */
  name?: string;
}

/**
 * Credential helper service for managing user credentials in bubble flows
 */
export class CredentialHelper {
  /**
   * Extracts credential IDs from bubble parameters and decrypts them
   * @param userId - The user ID to fetch credentials for
   * @param bubbleParameters - Parsed bubble parameters containing credential mappings
   * @returns Array of variable name to secret value mappings
   */
  static async getUserCredentials(
    userId: string,
    bubbleParameters: Record<string, ParsedBubble>
  ): Promise<UserCredentialMapping[]> {
    const credentialMappings: UserCredentialMapping[] = [];
    const credentialIds: number[] = [];
    const credentialIdToVarNames: Map<number, string[]> = new Map();

    // Extract credential IDs from bubble parameters
    for (const [varName, bubble] of Object.entries(bubbleParameters)) {
      // Look for credentials parameter in bubble
      const credentialsParam = bubble.parameters.find(
        (p) => p.name === 'credentials'
      );

      if (credentialsParam && credentialsParam.type === 'object') {
        try {
          // Parse the credentials object: { CredentialType -> credentialId }
          const credentialsObj = this.parseCredentialsObject(
            credentialsParam.value as Record<string, number | number[]>
          );

          for (const [, credentialIdOrIds] of Object.entries(credentialsObj)) {
            const ids = Array.isArray(credentialIdOrIds)
              ? credentialIdOrIds
              : [credentialIdOrIds];
            for (const credentialId of ids) {
              if (!credentialIds.includes(credentialId)) {
                credentialIds.push(credentialId);
              }
              // Support multiple variable names per credential ID
              if (!credentialIdToVarNames.has(credentialId)) {
                credentialIdToVarNames.set(credentialId, []);
              }
              credentialIdToVarNames.get(credentialId)!.push(varName);
            }
          }
        } catch (error) {
          console.warn(
            `Failed to parse credentials for bubble ${varName}:`,
            error
          );
        }
      }
    }

    // If no credential IDs found, return empty array
    if (credentialIds.length === 0) {
      return credentialMappings;
    }

    // Fetch encrypted credentials from database
    const encryptedCredentials = await db.query.userCredentials.findMany({
      where: and(
        eq(userCredentials.userId, userId),
        inArray(userCredentials.id, credentialIds)
      ),
    });

    // Decrypt credentials and map to variable names
    for (const encryptedCred of encryptedCredentials) {
      try {
        let resolvedSecret: string | null = null;

        if (encryptedCred.isOauth) {
          // Prefer using OAuth service to auto-refresh and return a valid token
          const oauthToken = await oauthService.getValidToken(encryptedCred.id);

          // Fallback: attempt to decrypt stored access token if service returned null
          if (!oauthToken && encryptedCred.oauthAccessToken) {
            try {
              resolvedSecret = await CredentialEncryption.decrypt(
                encryptedCred.oauthAccessToken
              );
            } catch (e) {
              // Ignore and let it fall through to skip
            }
          } else if (oauthToken) {
            // Special handling for Jira OAuth - encode token + cloudId as base64 JSON
            // Base64 encoding avoids JSON escaping issues when injecting into generated code
            if (
              encryptedCred.credentialType === 'JIRA_CRED' &&
              encryptedCred.metadata
            ) {
              const jiraMetadata = encryptedCred.metadata as unknown as {
                cloudId?: string;
                siteUrl?: string;
                siteName?: string;
              };
              if (jiraMetadata.cloudId) {
                // Encode Jira credential as base64-encoded JSON with token and cloudId
                const jsonPayload = JSON.stringify({
                  accessToken: oauthToken,
                  cloudId: jiraMetadata.cloudId,
                  siteUrl: jiraMetadata.siteUrl,
                });
                resolvedSecret = Buffer.from(jsonPayload).toString('base64');
                console.log(
                  '[CredentialHelper] Encoded Jira OAuth credential (base64) with cloudId:',
                  jiraMetadata.cloudId
                );
              } else {
                console.error(
                  '[CredentialHelper] Jira credential missing cloudId in metadata'
                );
                resolvedSecret = oauthToken;
              }
            } else {
              resolvedSecret = oauthToken;
            }
          }
        } else if (encryptedCred.isBrowserSession) {
          // Browser session credential - build base64-encoded JSON with contextId and decrypted cookies
          // Base64 encoding avoids JSON escaping issues when injecting into generated code
          if (encryptedCred.browserbaseContextId) {
            let cookies: unknown[] = [];
            if (encryptedCred.browserbaseCookies) {
              try {
                const decryptedCookies = await CredentialEncryption.decrypt(
                  encryptedCred.browserbaseCookies
                );
                cookies = JSON.parse(decryptedCookies);
              } catch (e) {
                console.warn(
                  `Failed to decrypt cookies for credential ${encryptedCred.id}:`,
                  e
                );
              }
            }
            // Build the session data payload as base64-encoded JSON
            const jsonPayload = JSON.stringify({
              contextId: encryptedCred.browserbaseContextId,
              cookies,
            });
            resolvedSecret = Buffer.from(jsonPayload).toString('base64');
          }
        } else if (encryptedCred.encryptedValue) {
          resolvedSecret = await CredentialEncryption.decrypt(
            encryptedCred.encryptedValue
          );
        }

        if (!resolvedSecret) {
          continue;
        }
        const varNames = credentialIdToVarNames.get(encryptedCred.id);

        if (varNames) {
          // Add a mapping for each variable name that uses this credential
          for (const varName of varNames) {
            credentialMappings.push({
              varName,
              secret: resolvedSecret,
              credentialType: encryptedCred.credentialType,
              credentialId: encryptedCred.id,
              metadata: encryptedCred.metadata || undefined,
              name: encryptedCred.name || undefined,
            });
          }
        }
      } catch (error) {
        console.error(
          `Failed to decrypt credential ${encryptedCred.id}:`,
          error
        );
        // Continue with other credentials even if one fails
      }
    }

    return credentialMappings;
  }

  /**
   * Parses a credentials object string to extract credential type to ID mappings
   * Expected format: { OPENAI_CRED: 1, SLACK_CRED: 2 }
   * @param credentialsValue - String representation of credentials object
   * @returns Object mapping credential types to credential IDs
   */
  private static parseCredentialsObject(
    credentialsValue: Record<string, number | number[]>
  ): Record<string, number | number[]> {
    // Validate that all values are numbers or arrays of numbers (credential IDs)
    const result: Record<string, number | number[]> = {};
    for (const [key, value] of Object.entries(credentialsValue)) {
      if (typeof value === 'number' && Number.isInteger(value)) {
        result[key] = value;
      } else if (Array.isArray(value)) {
        const validIds = value.filter(
          (v) => typeof v === 'number' && Number.isInteger(v)
        );
        if (validIds.length > 0) result[key] = validIds;
      } else {
        console.warn(`Skipping invalid credential ID for ${key}: ${value}`);
      }
    }

    return result;
  }
}

import {
  CredentialType,
  type DatabaseMetadata,
} from '@bubblelab/shared-schemas';
import { getBubbleFactory } from './bubble-factory-instance.js';
import { CredentialEncryption } from '../utils/encryption.js';
import type { IServiceBubble } from '@bubblelab/bubble-core';

export interface CredentialValidationResult {
  isValid: boolean;
  error?: string;
  bubbleName?: string;
}

export class CredentialValidator {
  /**
   * Validates a credential by instantiating the appropriate bubble and calling testCredential()
   */
  static async validateCredential(
    credentialType: CredentialType,
    credentialValue: string,
    skipValidation = false,
    configurations?: Record<string, unknown>
  ): Promise<CredentialValidationResult> {
    // Skip validation if explicitly requested
    // Skip Airtable validation because PATs have varying scopes and require specific base/table access
    if (skipValidation || credentialType === CredentialType.FIRECRAWL_API_KEY) {
      return { isValid: true };
    }

    // Get the bubble name for this credential type
    const factory = await getBubbleFactory();
    const bubbleName = factory.getBubbleNameForCredential(credentialType);
    if (!bubbleName) {
      return {
        isValid: true,
        error: `No service bubble implementation found for credential type: ${credentialType}, skipping validation`,
      };
    }

    try {
      // Check if bubble is registered
      const bubbleMetadata = factory.getMetadata(bubbleName);
      if (!bubbleMetadata) {
        return {
          isValid: false,
          error: `Bubble '${bubbleName}' is not registered`,
          bubbleName,
        };
      }

      // Create bubble instance with minimal parameters for testing
      const testParams = this.createTestParameters(credentialType);

      // Pass undefined to let the bubble use its default constructor parameters
      const bubbleInstance = factory.createBubble(
        bubbleName,
        Object.keys(testParams).length > 0 ? testParams : undefined
      );

      const serviceBubble = bubbleInstance as IServiceBubble;
      // Apply configurations if provided
      if (configurations) {
        for (const [paramName, paramValue] of Object.entries(configurations)) {
          serviceBubble.setParam(paramName, paramValue);
        }
      }
      serviceBubble.setParam('credentials', {
        [credentialType]: credentialValue,
      });
      const isValid = await serviceBubble.testCredential();

      return {
        isValid,
        error: isValid
          ? undefined
          : `Credential validation failed - please check your credentials`,
        bubbleName,
      };
    } catch (error) {
      console.error('Error validating credential', error);

      // Check for SSL-related errors and provide helpful guidance
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      const isSSLError =
        errorMessage.toLowerCase().includes('ssl') ||
        errorMessage.toLowerCase().includes('certificate') ||
        errorMessage.toLowerCase().includes('encryption') ||
        errorMessage.toLowerCase().includes('pg_hba.conf');

      let userFriendlyError = `We couldn't validate your credentials with the service - please check your credentials, error: ${errorMessage}`;

      if (isSSLError) {
        userFriendlyError =
          'SSL is enabled but the server\'s certificate could not be verified. If you are using a self-signed or custom certificate, enable the "Skip certificate verification (SSL stays enabled)" option in the connection settings. This disables certificate verification only; SSL encryption remains active. Also verify your host, port, and network allowlist settings. Original error: ' +
          errorMessage;
      }

      return {
        isValid: false,
        error: userFriendlyError,
        bubbleName,
      };
    }
  }

  /**
   * Validates an encrypted credential by decrypting it first
   */
  static async validateEncryptedCredential(
    credentialType: CredentialType,
    encryptedValue: string,
    skipValidation = false,
    configurations?: Record<string, unknown>
  ): Promise<CredentialValidationResult> {
    if (skipValidation) {
      return { isValid: true };
    }

    try {
      const decryptedValue = await CredentialEncryption.decrypt(encryptedValue);
      return this.validateCredential(
        credentialType,
        decryptedValue,
        skipValidation,
        configurations
      );
    } catch (error) {
      return {
        isValid: false,
        error: `Failed to decrypt credential: ${error instanceof Error ? error.message : String(error)}`,
      };
    }
  }

  /**
   * Creates minimal test parameters for bubble instantiation
   */
  private static createTestParameters(
    credentialType: CredentialType
  ): Record<string, unknown> {
    const baseParams: Record<string, unknown> = {};
    // Map credential types to their expected parameter names
    switch (credentialType) {
      case CredentialType.SLACK_CRED:
        break;
      case CredentialType.OPENAI_CRED:
        baseParams.message = 'Hello, how are you?';
        baseParams.model = {
          model: 'openai/gpt-5',
        };
        break;
      case CredentialType.ANTHROPIC_CRED:
        baseParams.message = 'Hello, how are you?';
        baseParams.model = {
          model: 'anthropic/claude-sonnet-4-5',
        };
        break;
      case CredentialType.GOOGLE_GEMINI_CRED:
        baseParams.message = 'Hello, how are you?';
        baseParams.model = {
          model: 'google/gemini-2.5-flash',
        };
        break;
      case CredentialType.GITHUB_TOKEN:
        baseParams.operation = 'get_repository';
        baseParams.owner = 'octocat';
        baseParams.repo = 'Hello-World';
        break;

      case CredentialType.OPENROUTER_CRED:
        baseParams.message = 'Hello, how are you?';
        baseParams.model = {
          model: 'openrouter/openai/gpt-oss-120b',
        };
        break;
      case CredentialType.ELEVENLABS_API_KEY:
        baseParams.operation = 'get_signed_url';
        baseParams.agentId = 'test-agent-id';
        break;
      case CredentialType.APIFY_CRED:
        baseParams.actorId = 'test-actor-id';
        baseParams.input = {
          message: 'Hello, how are you?',
        };
        break;
      case CredentialType.AIRTABLE_CRED:
        baseParams.operation = 'list_records';
        baseParams.baseId = 'test-base-id';
        baseParams.tableIdOrName = 'test-table';
        break;
      case CredentialType.NOTION_OAUTH_TOKEN:
      case CredentialType.NOTION_API:
        baseParams.operation = 'list_users';
        break;
      case CredentialType.JIRA_CRED:
        baseParams.operation = 'list_projects';
        break;
      case CredentialType.ASHBY_CRED:
        baseParams.operation = 'list_candidates';
        baseParams.limit = 1;
        break;
      case CredentialType.STRIPE_CRED:
        baseParams.operation = 'get_balance';
        break;
      default:
        break;
    }

    return baseParams;
  }

  /**
   * Gets the bubble name associated with a credential type
   */
  static async getBubbleNameForCredential(credentialType: CredentialType) {
    const factory = await getBubbleFactory();
    return factory.getBubbleNameForCredential(credentialType);
  }

  /**
   * Checks if a credential type supports validation
   */
  static async supportsValidation(
    credentialType: CredentialType
  ): Promise<boolean> {
    const factory = await getBubbleFactory();
    return factory.isCredentialSupported(credentialType);
  }

  /**
   * Gets metadata for a credential by instantiating the appropriate bubble and calling getCredentialMetadata()
   */
  static async getCredentialMetadata(
    credentialType: CredentialType,
    credentialValue: string,
    configurations?: Record<string, unknown>
  ): Promise<DatabaseMetadata | undefined> {
    // Get the bubble name for this credential type
    const factory = await getBubbleFactory();
    const bubbleName = factory.getBubbleNameForCredential(credentialType);
    if (!bubbleName) {
      return undefined;
    }

    try {
      // Check if bubble is registered
      const bubbleMetadata = factory.getMetadata(bubbleName);
      if (!bubbleMetadata) {
        return undefined;
      }

      // Create bubble instance with minimal parameters for testing
      const testParams = this.createTestParameters(credentialType);

      // Pass undefined to let the bubble use its default constructor parameters
      const bubbleInstance = factory.createBubble(
        bubbleName,
        Object.keys(testParams).length > 0 ? testParams : undefined
      );

      const serviceBubble = bubbleInstance as IServiceBubble;

      // Apply configurations if provided
      if (configurations) {
        for (const [paramName, paramValue] of Object.entries(configurations)) {
          serviceBubble.setParam(paramName, paramValue);
        }
      }
      serviceBubble.setParam('credentials', {
        [credentialType]: credentialValue,
      });

      // Get metadata using reflection to access protected method
      const metadata = await (
        serviceBubble as IServiceBubble
      ).getCredentialMetadata();

      return metadata;
    } catch (error) {
      console.error('Error getting credential metadata', error);
      return undefined;
    }
  }

  /**
   * Gets metadata for an encrypted credential by decrypting it first
   */
  static async getEncryptedCredentialMetadata(
    credentialType: CredentialType,
    encryptedValue: string,
    configurations?: Record<string, unknown>
  ): Promise<DatabaseMetadata | undefined> {
    try {
      const decryptedValue = await CredentialEncryption.decrypt(encryptedValue);
      return this.getCredentialMetadata(
        credentialType,
        decryptedValue,
        configurations
      );
    } catch (error) {
      console.error('Error decrypting credential for metadata', error);
      return undefined;
    }
  }
}
